input.command:
node <<'EOF'
const fs = require('fs'), path = require('path');
const files = [];
for (const dir of ['src', 'test']) for (const f of fs.readdirSync(dir)) if (f.endsWith('.js')) files.push(path.join(dir, f));
let renames = 0, attempts = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  let out = src.replace(/\bretryPolicy\b/g, () => { renames++; return 'backoffPolicy'; });
  out = out.replace(/maxAttempts: 3\b/g, () => { attempts++; return 'maxAttempts: 5'; });
  if (out !== src) fs.writeFileSync(f, out);
}
console.log(`renamed ${renames} occurrences, changed ${attempts} maxAttempts values`);
EOF
echo "--- remaining:"; grep -rn "retryPolicy\|maxAttempts: 3" src test; echo "--- tests:"; node --test 2>&1 | tail -n 25

